def xor_encrypt_decrypt(content: str, key: str) -> str:    """    基于异或算法的加解密函数（加解密使用同一函数）    Args:        content: 需要加密/解密的字符串内容        key: 加解密密钥（任意字符串）    Returns:        加密/解密后的字符串（加密后为不可见字符，会转成十六进制展示）    """    # 将字符串转换为字节串，便于逐字节处理    content_bytes = content.encode('utf-8')    key_bytes = key.encode('utf-8')    key_length = len(key_bytes)    # 存储处理后的字节    result_bytes = []    # 逐字节进行异或运算    for i, byte in enumerate(content_bytes):        # 循环使用密钥的每个字节（避免密钥长度不足）        key_byte = key_bytes[i % key_length]        # 异或运算        encrypted_byte = byte ^ key_byte        result_bytes.append(encrypted_byte)    # 如果是加密（输入是可见字符串），返回十六进制字符串（便于存储和传输）    # 如果是解密（输入是十六进制字符串），返回原始字符串    try:        # 尝试将结果转换为可见字符串（解密场景）        return bytes(result_bytes).decode('utf-8')    except UnicodeDecodeError:        # 转换失败说明是加密场景，返回十六进制字符串        return bytes(result_bytes).hex()def hex_to_bytes(hex_str: str) -> bytes:    """将十六进制字符串转换为字节串（解密前的预处理）"""    try:        return bytes.fromhex(hex_str)    except ValueError:        raise ValueError("无效的十六进制密文，请检查输入")def decrypt_from_hex(hex_cipher: str, key: str) -> str:    """    解密从加密函数得到的十六进制密文    Args:        hex_cipher: 加密后的十六进制字符串        key: 加密时使用的密钥    Returns:        解密后的原始字符串    """    # 将十六进制密文转回字节串    cipher_bytes = hex_to_bytes(hex_cipher)    key_bytes = key.encode('utf-8')    key_length = len(key_bytes)    # 逐字节异或解密    plain_bytes = []    for i, byte in enumerate(cipher_bytes):        key_byte = key_bytes[i % key_length]        plain_byte = byte ^ key_byte        plain_bytes.append(plain_byte)    # 转换回字符串    return bytes(plain_bytes).decode('utf-8')# 测试示例if __name__ == "__main__":    # 原始内容和密钥    original_content = "Hello, 这是需要加密的测试内容！"    secret_key = "my_secret_key_123"    print("=== 简单加解密 Demo ===")    print(f"原始内容: {original_content}")    print(f"加密密钥: {secret_key}")    # 加密    encrypted_hex = xor_encrypt_decrypt(original_content, secret_key)    print(f"\n加密后的密文（十六进制）: {encrypted_hex}")    # 解密    try:        decrypted_content = decrypt_from_hex(encrypted_hex, secret_key)        print(f"解密后的内容: {decrypted_content}")        # 验证是否一致        if decrypted_content == original_content:            print("\n? 加解密验证成功：解密后的内容与原始内容一致")        else:            print("\n? 加解密验证失败：内容不一致")    except Exception as e:        print(f"\n? 解密失败：{e}")